def T(head, rows, cls=None):
    h = '<table><thead><tr>' + ''.join('<th>%s</th>' % x for x in head) + '</tr></thead>'
    for i, r in enumerate(rows):
        c = (cls[i] if cls else '')
        h += '<tr class="%s">' % c + ''.join('<td>%s</td>' % x for x in r) + '</tr>'
    return h + '</table>'
def B(x): return '<b><bdi>%s</bdi></b>' % x
def E(x): return '<bdi>%s</bdi>' % x
